      used += 1;
      el.style.display = "";
      var color = parseRuntimeColor(item.color || "white");
      el.style.color = "rgba(" + Math.round(color[0] * 255) + "," + Math.round(color[1] * 255) + "," + Math.round(color[2] * 255) + "," + Math.max(0, Math.min(1, color[3])) + ")";
