    rec.axis3DVisualPanX = Number(rec.axis3DVisualPanX || 0) + (Number(dx) || 0);
    rec.axis3DVisualPanY = Number(rec.axis3DVisualPanY || 0) + (Number(dy) || 0);
    var transform = "translate3d(" + rec.axis3DVisualPanX + "px," + rec.axis3DVisualPanY + "px,0)";
