      (unifiedScene ? " (unified frame renderer)" : "") +
      (combinedTransparent ? " (combined transparent pass)" : "") +
      " camera=" + (camera ? JSON.stringify(camera.pos) : "none") +
      " lights=" + lights.length +
      " texts=" + textCount;
