      white: [1, 1, 1, 1],
      black: [0, 0, 0, 1],
      red: [1, 0.1, 0.1, 1],
      green: [0.15, 0.85, 0.15, 1],
      blue: [0.15, 0.35, 1, 1],
      yellow: [1, 0.9, 0.1, 1],
      cyan: [0.1, 0.9, 0.9, 1],
      magenta: [0.9, 0.1, 0.9, 1],
      orange: [1, 0.5, 0.05, 1],
      gray: [0.5, 0.5, 0.5, 1],
      grey: [0.5, 0.5, 0.5, 1]
